function scheduledDateOnly(value) {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString().split('T')[0];
  return String(value).split('T')[0];
}

function scheduledTimeOnly(value) {
  const raw = String(value || '').trim();
  return raw ? raw.slice(0, 5) : '08:00';
}

async function registerAcceptedEstimateAppointmentReminder({
  appointment,
  customerId,
  serviceType,
  appointmentReminders = AppointmentReminders,
}) {
  if (!appointment?.id || !customerId) return null;
  const date = scheduledDateOnly(appointment.scheduled_date);
  if (!date) return null;

  return appointmentReminders.registerAppointment(
    appointment.id,
    customerId,
    `${date}T${scheduledTimeOnly(appointment.window_start)}`,
    serviceType || appointment.service_type || 'Pest Control',
    'estimate_accept_slot',
    { sendConfirmation: false },
  );
}

// View-count hygiene. We surface view_count + last_viewed_at on the admin
// estimates dashboard, so the count needs to mean "the customer opened it"
// — not "iMessage unfurled the link" or "Virginia previewed it from the
// office." Three filters, applied to BOTH the view_count increment and the
// per-open estimate_views insert:
//   1. UA allowlist: drop anything whose user-agent matches a known bot /
//      preview / scanner / CLI client (shared with public-shortlinks via
//      utils/bot-ua so the shortlink click counter applies the same rules).
//   2. Admin marker cookie: a long-lived signed JWT set by /api/admin/auth
//      on every login + /me. Per-device, per-browser; survives network
//      changes.
//   3. Admin IP allowlist: legacy WAVES_ADMIN_IPS support for office/network
//      previews that do not carry the marker cookie.
// First-view side-effects (status flip + admin in-app notification) use the
// same gate; a filtered preview must not make the estimate look customer-opened.
const { isBotUserAgent } = require('../utils/bot-ua');

function clientIp(req) {
  return (req.headers['x-forwarded-for'] || req.ip || req.socket?.remoteAddress || '')
    .toString().split(',')[0].trim().slice(0, 64);
}

// estimates.customer_phone may be freeform (admin input) or E.164 (quote
// wizard) while customers.phone is freeform — compare on the last 10 digits
// like admin-customers/admin-communications do, never on the raw string.
function phoneLast10(phone) {
  const digits = String(phone || '').replace(/\D/g, '');
  return digits.length >= 10 ? digits.slice(-10) : '';
}

function normalizeAddressForMatch(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

// Multiple live profiles can legitimately share a phone (landlord + rental
// property via quick-add). Only reuse one when the match is unambiguous: a
// single phone hit, or — among several — a unique email or service-address
// match. Otherwise return null so the accept creates a fresh profile;
// attaching the tier/monthly_rate/schedules to a guessed profile splits the
// real customer's history.
function pickAcceptCustomerMatch(candidates, estimate) {
  if (!candidates.length) return null;
  if (candidates.length === 1) return candidates[0];
  let pool = candidates;
  const email = String(estimate.customer_email || '').trim().toLowerCase();
  if (email) {
    const byEmail = pool.filter((c) => String(c.email || '').trim().toLowerCase() === email);
    if (byEmail.length === 1) return byEmail[0];
    if (byEmail.length > 1) pool = byEmail;
  }
  const estAddr = normalizeAddressForMatch(estimate.address);
  if (estAddr) {
    const byAddress = pool.filter((c) => {
      const line1 = normalizeAddressForMatch(c.address_line1);
      // estimate.address is the full address; address_line1 is the street
      // line. Require a meaningful street line so '' never matches, and a
      // token boundary so '12 oak' can't match '12 oakridge dr'.
      return line1.length >= 5 && (estAddr === line1 || estAddr.startsWith(line1 + ' '));
    });
    if (byAddress.length === 1) return byAddress[0];
  }
  return null;
}

// The accept-time customer resolution for UNLINKED estimates, shared with the
// recurring-card resolver (Codex #2680 r3: /data and /recurring-card-intent
// must see the same customer accept will land on, or an existing customer
// with a saved consented card / active Auto Pay is re-asked for a card the
// auto-satisfy contract says they never re-enter). Read-only; pass the accept
// transaction as `database` to keep the in-trx behavior identical.
async function matchAcceptCustomerByPhone(estimate, database = db) {
  if (!estimate?.customer_phone) return { match: null, candidateCount: 0 };
  const matchDigits = phoneLast10(estimate.customer_phone);
  const candidates = await database('customers')
    .where((q) => {
      q.where({ phone: estimate.customer_phone });
      if (matchDigits) {
        q.orWhereRaw("regexp_replace(COALESCE(phone, ''), '[^0-9]', '', 'g') LIKE ?", [`%${matchDigits}`]);
      }
    })
    .whereNull('deleted_at')
    .orderByRaw('(phone = ?) DESC NULLS LAST', [estimate.customer_phone])
    .orderBy('updated_at', 'desc');
  return { match: pickAcceptCustomerMatch(candidates, estimate), candidateCount: candidates.length };
}

// Tiny cookie-header parser — avoids pulling in cookie-parser for one read.
function readCookie(req, name) {
  const header = req.headers.cookie;
  if (!header) return null;
  const target = name + '=';
  for (const part of header.split(';')) {
    const trimmed = part.trim();
    if (trimmed.startsWith(target)) {
      try { return decodeURIComponent(trimmed.slice(target.length)); } catch { return null; }
    }
  }
  return null;
}

function hasAdminMarker(req) {
  const token = readCookie(req, 'waves_admin');
  if (!token) return false;
  try {
    const payload = jwt.verify(token, config.jwt.secret);
    return payload && payload.kind === 'admin_marker';
  } catch { return false; }
}

function requestUserAgent(req) {
  if (typeof req?.get === 'function') return req.get('user-agent');
  return req?.headers?.['user-agent'] || req?.headers?.['User-Agent'] || '';
}

function estimateHasBeenSent(estimate) {
  if (!estimate) return true;
  return !!estimate.sent_at;
}

function shouldCountView(req, ip, estimate = null) {
  if (!estimateHasBeenSent(estimate)) return false;
  // Expired links don't count as views or fire first-view side effects (status
  // flip + admin "Estimate viewed" notify). The legacy server-HTML path
  // short-circuits to the expired page before any view tracking; the React
  // /:token/data path reaches here instead, so the guard lives centrally so
  // both renderers agree. Accepted estimates past expiry still render + count
  // (mirrors the `status !== 'accepted'` carve-out in handleEstimateView).
  if (estimate && estimate.expires_at
    && new Date(estimate.expires_at) < new Date()
    && estimate.status !== 'accepted') return false;
  if (isBotUserAgent(requestUserAgent(req))) return false;
  if (hasAdminMarker(req)) return false;
  if (isAdminIp(ip)) return false;
  return true;
}

function shouldApplyFirstViewSideEffects(req, ip, estimate = null) {
  return shouldCountView(req, ip, estimate);
}

function hashEstimateToken(token) {
  return crypto.createHash('sha256').update(String(token || '')).digest('hex');
}

function signEstimateAskToken(estimate = {}, tokenOverride) {
  const token = tokenOverride || estimate.token;
  return jwt.sign({
    kind: 'estimate_ask',
    estimateId: String(estimate.id || ''),
    tokenHash: hashEstimateToken(token),
  }, ESTIMATE_ASK_TOKEN_SECRET, { expiresIn: ESTIMATE_ASK_TOKEN_TTL_SECONDS });
}

function verifyEstimateAskToken(req, estimate) {
  const supplied = req.get('x-estimate-ask-token') || req.body?.askToken;
  if (!supplied) return false;
  try {
    const payload = jwt.verify(String(supplied), ESTIMATE_ASK_TOKEN_SECRET);
    return payload?.kind === 'estimate_ask'
      && String(payload.estimateId || '') === String(estimate.id || '')
      && payload.tokenHash === hashEstimateToken(estimate.token || req.params.token);
  } catch {
    return false;
  }
}

function isEstimateAskAnswerable(estimate = {}, now = new Date()) {
  if (!estimate) return false;
  if (estimate.archived_at) return false;
  // A previously issued ask token must die with the estimate (codex P0,
  // PR #3304 GH r9b): while a live delivery claim defers invalidation into
  // invalidation_pending_at the row is not yet archived, and this endpoint
  // would keep answering questions about — and disclosing — the wrong
  // lead's estimate content.
  if (estimateLinkageInvalidated(estimate)) return false;
  if (['accepted', 'declined', 'expired', 'send_failed'].includes(estimate.status)) return false;
  if (estimate.expires_at && new Date(estimate.expires_at) < now) return false;
  return true;
}

function buildEstimateAskQueryLog({ estimateId, question, result = {} }) {
  const questionChars = String(question || '').length;
  const answerChars = String(result.answer || '').length;
  const source = String(result.source || 'unknown').replace(/[^a-z0-9_-]/gi, '').slice(0, 40) || 'unknown';
  return {
    prompt: `[public_estimate:${estimateId}] question_chars=${questionChars}`,
    response: `[redacted] source=${source} answer_chars=${answerChars}`,
    tool_calls: JSON.stringify([{
      name: 'public_estimate_ask',
      input: { questionChars },
      result: { source, answerChars },
    }]),
    operator_id: null,
  };
}

// Map a one-time service name to the booking page's service id (matches PublicBookingPage SERVICES)
function bookingServiceFor(name) {
  const n = String(name || '').toLowerCase();
  // Bora-Care is checked before termite/pest so a "Bora-Care Wood Treatment" (or
  // "Termite Bora-Care") label routes the /book link + SMS to the Bora-Care visit
  // instead of falling through to the Pest Control bucket.
  if (n.includes('bora') || n.includes('borate')) return { id: 'bora_care', label: 'Bora-Care Wood Treatment Service' };
  if (n.includes('lawn') || n.includes('turf') || n.includes('aeration') || n.includes('seed') || n.includes('weed')) return { id: 'lawn_care', label: 'Lawn Care' };
  if (n.includes('mosquito')) return { id: 'mosquito', label: 'Mosquito Control' };
  if (n.includes('tree') || n.includes('shrub') || n.includes('palm') || n.includes('ornamental')) return { id: 'tree_shrub', label: 'Tree & Shrub Service' };
  if (n.includes('termite') || n.includes('wdo')) return { id: 'termite', label: 'Termite Inspection' };
  if (n.includes('rodent') || n.includes('rat') || n.includes('mouse')) return { id: 'rodent', label: 'Rodent Control' };
  return { id: 'pest_control', label: 'Pest Control' };
}

// Customer-facing service name for the post-booking confirmation SMS.
// Prefer the specific one-time service the customer actually scheduled
// (e.g. "German Roach Cleanout") over the generic booking bucket that
// bookingServiceFor collapses roach/specialty services into — that bucket
// is correct for routing the /book link's ?service= param but reads wrong
// as confirmation copy once a real appointment exists. Falls back to the
// estimate's service_interest, then the supplied bucket label.
// An itemized job's component rows share a "<Job> — <Section>" label. For
// acceptance/confirmation copy the customer accepted the JOB, so a label
// that is one section of a multi-section job collapses to the job name
// (codex #3521 r13 P2); a lone section-labelled row keeps its label.
function jobLevelOneTimeLabel(label, rows = []) {
  const text = String(label || '').trim();
  const sep = text.indexOf(' — ');
  if (sep <= 0) return text;
  const prefix = text.slice(0, sep).trim();
  const siblings = (Array.isArray(rows) ? rows : []).filter((r) => {
    const name = String(r?.name || r?.label || r?.displayName || '').trim();
    const i = name.indexOf(' — ');
    return i > 0 && name.slice(0, i).trim().toLowerCase() === prefix.toLowerCase();
  });
  return siblings.length > 1 ? prefix : text;
}

function confirmationServiceLabel(oneTimeList, estimate, fallbackLabel) {
  const specific = (Array.isArray(oneTimeList) ? jobLevelOneTimeLabel(oneTimeList[0]?.name, oneTimeList) : '')
    || estimate?.service_interest
    || fallbackLabel
    || '';
  return String(specific).replace(/\s+/g, ' ').trim() || String(fallbackLabel || '').trim();
}

function dateOnly(value) {
  if (!value) return '';
  if (value instanceof Date) return value.toISOString().split('T')[0];
  return String(value).split('T')[0];
}

function hhmm(value) {
  return value ? String(value).slice(0, 5) : '';
}

function parseEstimateDataSafe(estimate = {}) {
  const raw = estimate.estimate_data;
  if (!raw) return {};
  if (typeof raw === 'string') {
    try { return JSON.parse(raw) || {}; } catch { return {}; }
  }
  return raw || {};
}

// Customer-facing fallback when scheduled_services.window_display is empty:
// the 2-hour arrival window from window_start ("3:00 PM - 5:00 PM"), matching
// the confirmation SMS — never the raw 24h window_start, and never window_end
// (that's the job-duration block, not the arrival window).
function customerArrivalWindowDisplay(windowStart) {
  const range = arrivalWindowRange(windowStart);
  return range ? formatSmsTimeRange(range) : null;
}

// SSR existing-appointment title. windowDisplay is a TIME display (stored
// values are "11:00 AM"-style; the fallback above is the arrival range), so
// the date must be composed in here — mirrors the React formatAppointmentLabel.
function existingAppointmentTitle(appointment = {}) {
  const date = appointment.scheduledDate
    ? new Date(`${appointment.scheduledDate}T12:00:00Z`).toLocaleDateString('en-US', {
      weekday: 'long', month: 'long', day: 'numeric', timeZone: 'America/New_York',
    })
    : '';
  const time = appointment.windowDisplay || appointment.windowStart || '';
  return [date, time].filter(Boolean).join(' · ') || 'Your scheduled appointment';
}

function shapeLinkedAppointment(row) {
  if (!row) return null;
  return {
    id: row.id,
    scheduledDate: dateOnly(row.scheduled_date),
    windowStart: hhmm(row.window_start),
    windowEnd: hhmm(row.window_end),
    // Derived 2h arrival range FIRST: prod window_display values are only ever
    // a bare start time ("9:00 AM" — the phone-booking writer) or NULL, never a
    // range, so stored text can only lose information vs deriving from
    // window_start. Stored text is the fallback for rows with no parseable start.
    windowDisplay: customerArrivalWindowDisplay(row.window_start) || row.window_display || null,
    serviceType: row.service_type || 'Service visit',
    status: row.status || null,
  };
}

// serviceKeyFor's fallback for names that resolve to no known family. Both
// sides of the adoption match must treat it as "no family": letting two
// unclassifiable labels match each other would adopt an arbitrary row.
const SERVICE_FAMILY_FALLBACK_KEY = 'service';

function classifyServiceFamilyText(text) {
  // Separators normalize to spaces BEFORE any word-boundary test (codex
  // #3228 r7): combined catalog keys like pest_termite_bait_quarterly
  // otherwise defeat \b rules — the underscore glues "pest" to the next
  // token, the pest-primary combined rule misses, and serviceKeyFor's
  // termite branch claims an intentionally pest-primary series.
  const raw = String(text || '').toLowerCase().replace(/[_-]+/g, ' ').trim();
  if (!raw) return null;
  // Generic catch-all placeholders have NO family (codex #3228 r21): the
  // general_appointment catalog row is explicitly an anything-row whose
  // proper service is still unassigned — serviceKeyFor's "general" token
  // would file it under pest and let it swallow a pest estimate's booking.
  // Same names the call-booking generic-row predicate treats as anything-rows.
  if (/^general appointment$|^waves pest control appointment service$|^waves assessment$|^waves appointment$/.test(raw)) {
    return null;
  }
  // Palm precedence (codex #3228 r3): serviceKeyFor checks the tree token
  // before its palm branch, so "Palm Tree Injections" buckets as
  // tree_shrub there — fine for its cadence defaults, but adoption must
  // never let a tree & shrub estimate swallow a palm visit. Same palm
  // rule as detectServiceLine / toQualifyingKeys: \bpalms?\b never
  // matches "palmetto", so palmetto-bug pest names fall through.
  if (/\bpalms?\b/.test(raw)) return 'palm_injection';
  // Commercial stays a DISTINCT family (codex #3228 r5): the seeder's
  // generic lawn/tree branches run before any commercial distinction, so
  // "Commercial Lawn" would collapse into residential lawn_care and a
  // residential visit could suppress the commercial manual-scheduling
  // path (or vice versa). recurringServiceKey keeps commercial_* keys
  // separate — delegate commercial names to it.
  if (raw.includes('commercial')) {
    return recurringServiceKey({ name: raw }) || null;
  }
  // Bora-Care is a borate wood treatment, never trenching (codex #3228
  // r13): recurringServiceKey's generic termite+treatment rule would map
  // "Bora-Care Termite Treatment" to termite_trenching and let it adopt a
  // liquid-trenching visit. Same rule as isBoraCareOneTimeItem.
  if (/\bbora\s*care\b/.test(raw) || raw.includes('borate')) return 'bora_care';
  // Foam spot treatments are NOT trenching (codex #3228 r12):
  // recurringServiceKey's termidor/treatment tokens would claim
  // "Termidor Foam Spot Treatment" for termite_trenching and let a foam
  // accept adopt a liquid-trenching visit. Mirror
  // isTermiteFoamOneTimeItem's foam split — the RECURRING foam program
  // stays the seeder's foam_recurring family (delegated below).
  // The optional "termite" token covers the 2026-08-25 renamed label
  // ("Recurring Termite Foam Service") — without it a relabeled legacy
  // visit (null service_id) would classify as one-time termite_foam and
  // the accept would duplicate the existing foam appointment (codex P1).
  const isRecurringFoam = /foam\s*recurring|recurring\s*(?:termite\s*)?foam/.test(raw);
  if (!isRecurringFoam && raw.includes('foam')) return 'termite_foam';
  // Termite work keeps its specialty split (codex #3228 r11): serviceKeyFor's
  // generic termite branch buckets liquid / trenching WITH the bait
  // program, so a one-time specialty treatment could adopt (and restamp) a
  // termite-bait visit. recurringServiceKey already splits termite_bait /
  // termite_trenching / pre_slab_termiticide — delegate termite names to
  // it. Its pest-first ordering also keeps combined pest+termite rows
  // pest-primary.
  if (raw.includes('termite')) {
    return recurringServiceKey({ name: raw }) || null;
  }
  // Roach work shares ONE identity across vocabularies (codex #3228 r23):
  // engine german_roach / "German Roach Cleanout" vs the catalog booking
  // row cockroach_control / "Cockroach Treatment" — independent slugs never
  // intersect and a valid upcoming cockroach visit would be rejected into a
  // duplicate. \b keeps "approach"-style words out.
  if (/\b(?:cock)?roach(?:es)?\b/.test(raw)) return 'cockroach_control';
  // Rodent work keeps the slot profile's split (codex #3228 r18): the
  // seeder buckets EVERY rodent row as rodent_bait, but slot-reservation's
  // serviceKeyForLabel deliberately distinguishes trapping / exclusion /
  // sanitation from bait — sold exclusion or trapping work must never adopt
  // (and restamp) a bait-station monitoring visit. Same regexes as
  // slot-reservation.
  if (/rodent.*trap|trap.*rodent/.test(raw)) return 'rodent_trapping';
  // Wire-mesh/seal wording is exclusion work (codex r19: the supported
  // rodent_wire_mesh catalog key carries no "exclusion" token).
  // Guarantee combos include full exclusion work (codex r22:
  // rodent_guarantee_combo / "Rodent Guarantee") — classify under the
  // exclusion identity, never bait.
  if (/rodent.*(?:exclusion|wire\s*mesh|seal|bird\s*box|guarantee)|(?:exclusion|wire\s*mesh|seal|bird\s*box|guarantee).*rodent/.test(raw)) return 'rodent_exclusion';
  if (/rodent.*sanitation|sanitation.*rodent/.test(raw)) return 'rodent_sanitation';
  // Diagnostic inspections are their own identity too (codex r20:
  // priceRodentInspection's standalone rodent_inspection item). \b after
  // inspect(ion) keeps "inspector" out — "the home inspector found rats"
  // names a person, not the service (same rule as the call-booking matcher).
  if (/rodent.*\binspect(?:ion)?s?\b|\binspect(?:ion)?s?\b.*rodent/.test(raw)) return 'rodent_inspection';
  // Stinging-insect work shares ONE identity across vocabularies (codex
  // r22): engine keys say stinging_insect*, the catalog row says
  // bee_wasp_removal — independently generated slugs never intersect and a
  // valid existing visit would be rejected into a duplicate booking.
  if (/stinging|\bwasps?\b|\bhornets?\b|\bbees?\b|yellow\s*jacket/.test(raw)) return 'stinging_insect';
  // The CANONICAL scheduled-row classifier (recurring-appointment-seeder),
  // on BOTH the estimate's services and the candidate rows — the
  // duplicate-series guard and follow-up seeding bucket by the same
  // function, so "may this row stand in" and "would seeding treat these
  // as one family" can never disagree (codex #3228 r1). Its palm branch
  // is substring-based ("Palmetto Bug Pest Control" would bucket palm);
  // real palms were consumed above, so strip the palmetto token.
  const { serviceKeyFor } = require('../services/recurring-appointment-seeder');
  const key = serviceKeyFor({ name: raw.replace(/palmetto/g, ' ') });
  return key && key !== SERVICE_FAMILY_FALLBACK_KEY ? key : null;
}

// STAGED per-field classification — first field that resolves wins. Fields
// are never concatenated: joining a service key with its display name minted
// synthetic slug families no scheduled row could reproduce (codex #3228
// r13, `flea_package` + "Flea Treatment Package"), and mixing service_type
// into catalog identity would let a stale label override it (r5 guarantee).
function serviceFamilyKeyForAdoption(value) {
  const fields = [
    value?.service, value?.service_key, value?.key, value?.kind,
    value?.name, value?.label, value?.displayName, value?.service_type,
  ];
  for (const field of fields) {
    const key = classifyServiceFamilyText(field);
    if (key) return key;
  }
  return null;
}

// Vocabulary bridge: serviceCategoryForOneTimeItem speaks category keys; the
// scheduled-row side speaks the seeder/route family keys. Identical except
// rodent, where the seeder buckets every rodent row as rodent_bait.
const ONE_TIME_CATEGORY_FAMILIES = { rodent: ['rodent', 'rodent_bait'] };

// Family keys a ONE-TIME item may adopt under (codex #3228 r13):
//   1. non-service rows (setup fees, discounts) adopt nothing;
//   2. Bora-Care/foam keep their specialty precedence (r11/r12 — the
//      category classifier's generic termite heuristics run after these);
//   3. the canonical serviceCategoryForOneTimeItem identity, bridged to the
//      row vocabulary;
//   4. otherwise a per-field classification UNION — a single field's stable
//      slug can match the row's label-derived slug (flea packages), which
//      concatenation broke.
function oneTimeItemFamilyKeys(item = {}) {
  if (isNonServiceOneTimeItem(item)) return [];
  if (isBoraCareOneTimeItem(item)) return ['bora_care'];
  const joined = [
    item?.service, item?.service_key, item?.key, item?.kind,
    item?.name, item?.label, item?.displayName,
  ].filter(Boolean).join(' ').toLowerCase().replace(/[_-]+/g, ' ');
  if (!/foam\s*recurring|recurring\s*foam/.test(joined) && joined.includes('foam')) {
    return ['termite_foam'];
  }
  const fields = [
    item?.service, item?.service_key, item?.key, item?.kind,
    item?.name, item?.label, item?.displayName,
  ];
  const category = serviceCategoryForOneTimeItem(item);
  // A SPECIALTY in a broad category must never make an ordinary visit of
  // that category adoptable (codex #3228 r16/r17): acceptance restamps the
  // adopted row's source and price without changing its service identity,
  // so the specialty work (flea package, roach treatment, top dressing,
  // dethatching, plugging) never reaches dispatch. Generic pest = the
  // derived one-time pest choice or a plainly pest-named line.
  const genericPest = isOneTimePestChoiceItem(item)
    || String(item?.service || '').toLowerCase() === 'one_time_pest'
    || isPestServiceName(item?.name || item?.label || '');
  const specialtyText = fields.filter(Boolean).join(' ').toLowerCase();
  const lawnSpecialty = /top[ -_]?dress|dethatch|\bplugging\b/.test(specialtyText);
  if ((category === 'pest_control' && !genericPest) || lawnSpecialty) {
    // Specific identities ONLY — no BROAD families, whose pest/roach and
    // lawn tokens would re-add them through the field union (codex r17).
    // Specific (non-broad) classifier families still participate (codex
    // r22): the stinging_insect identity is how an engine-keyed specialty
    // meets its catalog-keyed row. Anything else goes to the slot picker
    // (fail-safe).
    const slugKeys = new Set();
    for (const field of fields) {
      const slug = String(field || '').toLowerCase()
        .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
      if (slug && !BROAD_ADOPTION_FAMILY_KEYS.has(slug)) slugKeys.add(slug);
      const famKey = classifyServiceFamilyText(field);
      if (famKey && !BROAD_ADOPTION_FAMILY_KEYS.has(famKey)) slugKeys.add(famKey);
    }
    return [...slugKeys];
  }
  // Canonical category AND per-field keys merge for generic items: the
  // category supplies the semantic family while a single field's stable
  // slug still matches a row whose label is the only identity it has
  // (codex #3228 r13).
  const keys = new Set();
  for (const field of fields) {
    const key = classifyServiceFamilyText(field);
    if (key) keys.add(key);
  }
  // Specific rodent identities EXCLUDE the bait family entirely (codex
  // #3228 r18/r19): when any field resolves trapping / exclusion /
  // sanitation, a bait key contributed by ANOTHER field of the same item
  // (rodent_wire_mesh's service key has no exclusion token) must be
  // removed too — suppressing only the category bridge left it in place
  // and a bait-station monitoring visit stayed adoptable.
  const hasSpecificRodent = [...keys].some(
    (k) => k === 'rodent_trapping' || k === 'rodent_exclusion'
      || k === 'rodent_sanitation' || k === 'rodent_inspection',
  );
  if (hasSpecificRodent) {
    keys.delete('rodent_bait');
    keys.delete('rodent');
  }
  if (category) {
    if (!(category === 'rodent' && hasSpecificRodent)) {
      for (const key of (ONE_TIME_CATEGORY_FAMILIES[category] || [category])) keys.add(key);
    }
  }
  return [...keys];
}

// Family keys the specialty slug path must never emit — a specialty item
// whose field happens to BE a family key (service: 'pest_control' on a
// mislabeled row) must not become broad-adoptable through the slug door.
const BROAD_ADOPTION_FAMILY_KEYS = new Set([
  'pest_control', 'lawn_care', 'tree_shrub', 'mosquito', 'palm_injection',
  'termite_bait', 'termite_trenching', 'pre_slab_termiticide', 'termite_foam',
  'foam_recurring', 'bora_care', 'rodent', 'rodent_bait',
]);

// Service families this estimate actually covers — the only families whose
// existing appointment may stand in for the estimate's first visit (see the
// customer-wide fallback in findLinkedUpcomingAppointment). Derived from the
// same acceptance lists the accept handler schedules from, so "what we'd
// book" and "what an existing row may replace" can never disagree.
function estimateFamilyKeysForAdoption(estimate, estData, { serviceMode, serviceModes } = {}) {
  // Input-only estimates (engineInputs persisted, no stored result) replay
  // through the SAME supplement path acceptance and the converter use (codex
  // #3228 r10) — raw data would derive no recurring family, skip the
  // adoption fallback, and let the customer book a duplicate visit. The
  // replay only fires when no stored services exist; normal shapes pass
  // through untouched.
  let effectiveData = estData || {};
  try {
    effectiveData = withSupplementedRecurringServices(effectiveData);
  } catch { /* raw data stands */ }
  const { recurringSvcList, oneTimeList } = acceptanceServiceLists(effectiveData);
  // The ONE-TIME family comes from the same effective-choice mechanism the
  // accept uses (codex #3228 r9): when show_one_time_option derives a pest
  // offer from recurring pricing, the STORED one-time rows may hold only the
  // WaveGuard setup fee — classifying those would empty the contract-time
  // intersection and reject a valid same-family appointment. Acceptance
  // swaps in the one_time_pest choice via acceptedOneTimeChoiceListForEstimate,
  // so family derivation must read the same list. Fail-soft to the stored
  // rows — a derivation error must not break the matcher.
  let effectiveOneTimeList = oneTimeList;
  try {
    const choiceList = acceptedOneTimeChoiceListForEstimate(estimate || {}, effectiveData);
    if (Array.isArray(choiceList) && choiceList.length > 0) effectiveOneTimeList = choiceList;
  } catch { /* stored rows stand */ }
  // Scoped to the accepted service mode (codex #3228 r4): a mixed estimate
  // (recurring pest + one-time Bora-Care) must not let a one-time-family
  // appointment stand in for the RECURRING plan's first visit — acceptance
  // would treat the adopted row as the recurring reservation and stamp the
  // recurring first-application price onto it.
  //
  // MULTIPLE modes intersect (codex #3228 r5 P1): the /data contract is
  // built once, but a mixed estimate lets the customer toggle modes AFTER
  // the contract rendered — an existing_appointment contract valid only
  // under the default mode dead-ends the alternate mode client-side (the
  // accept 409s while the picker stays hidden). Contract sites therefore
  // pass every mode the customer can select and only a row adoptable under
  // ALL of them is offered; the accept path passes the single selected mode.
  const modes = (Array.isArray(serviceModes) && serviceModes.length > 0)
    ? serviceModes
    : [serviceMode || 'recurring'];
  const keySets = modes.map((mode) => {
    if (mode === 'one_time') {
      // PRIMARY service only (codex #3228 r13): a multi-service one-time
      // accept (pest + Bora-Care) books ONE appointment under the primary
      // service — the first bookable list item, same as the accept's
      // booking-service resolution. Letting an ADD-ON family adopt would
      // restamp a standalone add-on visit while the primary work never
      // reaches dispatch.
      const primary = (effectiveOneTimeList || [])
        .map((item) => oneTimeItemFamilyKeys(item))
        .find((keys) => keys.length > 0);
      return new Set(primary || []);
    }
    // PRIMARY service here too (codex #3228 r14): a multi-service recurring
    // accept books its reserved row under the primary line — the converter's
    // reserved-row path deliberately does NOT schedule ordinary remaining
    // services — so letting an add-on family adopt (pest-plus-tree plan
    // adopting a tree & shrub visit) restamps the add-on row while the
    // primary pest work is never scheduled. Primary selection mirrors the
    // reservation writer (slot-reservation canonicalServiceTypeForProfile,
    // codex r15): pest_control ANYWHERE in the profile is the primary — a
    // tree-first, pest-second list still reserves a pest visit — otherwise
    // the first classifiable line.
    const recurringKeys = (recurringSvcList || [])
      .map((svc) => serviceFamilyKeyForAdoption(svc))
      .filter(Boolean);
    const primaryRecurring = recurringKeys.includes('pest_control')
      ? 'pest_control'
      : recurringKeys[0];
    return new Set(primaryRecurring ? [primaryRecurring] : []);
  });
  return keySets.reduce((acc, set) => new Set([...acc].filter((k) => set.has(k))));
}

// Whether an existing scheduled_services row belongs to one of the estimate's
// service families. Rows whose service_type doesn't resolve to a family key
// (generic assessment shells, blank types) never match — adopting them would
// re-create the cross-family clobber this guard exists to prevent.
function appointmentMatchesEstimateFamily(row = {}, familyKeys = new Set()) {
  // Catalog identity first (codex #3228 r5): a stale service_type label
  // ("Tree & Shrub Care" on a row whose service_id links palm_injection)
  // must classify by what the row actually IS — the same catalog-first rule
  // waveguard-existing-services applies. service_type remains the fallback
  // for unlinked legacy rows.
  const key = serviceFamilyKeyForAdoption({
    service: row.catalog_service_key || null,
    name: row.catalog_service_name || null,
    service_type: row.service_type,
  });
  if (key && familyKeys.has(key)) return true;
  // Symmetric specialty slugs (codex #3228 r18): specialty items emit
  // slug-only identities, but the row's broad classification (a roach row
  // buckets pest_control) could never meet them — an appointment labeled
  // exactly "Cockroach Treatment" was rejected and the customer sent to
  // book a duplicate. The row's own field slugs may satisfy a specialty
  // key; broad family-key slugs stay excluded so this door never widens
  // generic adoption. Catalog authority holds here too (codex r19): when
  // the row is catalog-linked, only the catalog fields may supply slugs —
  // a stale service_type snapshot ("Cockroach Treatment" on an ordinary
  // pest catalog row) must not resurrect the match the catalog family
  // check just rejected.
  const slugFields = (row.catalog_service_key || row.catalog_service_name)
    ? [row.catalog_service_key, row.catalog_service_name]
    : [row.service_type];
  for (const field of slugFields) {
    const slug = String(field || '').toLowerCase()
      .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
    if (slug && !BROAD_ADOPTION_FAMILY_KEYS.has(slug) && familyKeys.has(slug)) return true;
  }
  return false;
}

// Property-scope predicate for appointment ADOPTION, shared by the
// customer-wide selector below and the accept path's under-lock recheck.
// EVERY estimate with an address is scoped — not just grouped ones. The
// grouped-only arming (codex #3244 r8) left ordinary estimates fully
// property-blind: an existing customer accepting a plan for a NEW property
// adopted their OLD property's upcoming visit as the plan's first visit
// (cross-property accept incident, 08-15 — the adopted row then suppressed
// new-visit creation, the dup-series guard matched the old property's
// series so the new property's series never seeded, and the first-service
// invoice attached to the old property's visit).
//
// property_id is authoritative when BOTH sides carry it. Otherwise the
// street compare: a candidate's stamped service address, falling back to
// the customer's fully-qualified primary address for fully-unstamped rows
// (the single-property common case — primary === estimate address, still
// adopts). Keys are UNIT-AWARE (codex #3431 r2 P1): the unit token
// discriminates only when the estimate supplies one, so a legacy unitless
// estimate still adopts at the customer's unit-bearing primary
// (makeEstimateScopeKeys — the estimateQuotesCustomerAddress semantics).
// Adoption consumes a real visit — the highest-stakes scope consumer — so
// it fails CLOSED on candidates that cannot prove their locality. The only
// fail-open escape is an estimate with no property evidence at all (no
// property_id, no parseable address) — the historical behavior. The
// customer read is lazy + memoized: the selector loops paged candidates
// and must not re-read per candidate.
function makeAdoptionPropertyScope(conn, estimate) {
  const {
    makeEstimateScopeKeys, sameScopeKey, scopeKeyLacksLocality, scopeKeysShareLocality,
  } = require('../services/estimate-property-linkage');
  const scopeKeys = makeEstimateScopeKeys(estimate.address);
  const estimateStreet = scopeKeys ? scopeKeys.estimateKey : '';
  let primaryStreetPromise = null;
  const primaryStreet = () => {
    if (!primaryStreetPromise) {
      primaryStreetPromise = (async () => {
        try {
          const cust = await conn('customers').where({ id: estimate.customer_id }).first('address_line1', 'address_line2', 'city', 'zip');
          // primaryKey, not candidateKey (codex #3431 r9): the unitless-
          // compatibility mode applies ONLY to the customer's known
          // primary — independently stamped candidates keep unit identity.
          return scopeKeys.primaryKey(cust?.address_line1, cust?.address_line2, cust?.city, cust?.zip);
        } catch {
          return '';
        }
      })();
    }
    return primaryStreetPromise;
  };
  return async (cand) => {
    if (estimate.property_id && cand?.property_id) {
      return String(cand.property_id) === String(estimate.property_id);
    }
    // A property_id-LINKED estimate with no usable address still has
    // property evidence (codex #3431 r5 P1): an unstamped candidate
    // without an id cannot prove it belongs to that property — fail
    // closed. A STRUCTURED locality-bearing parse that merely lacks a
    // house number (a named commercial building — a real input class,
    // see unit-scope-model's no-street-number docs) is also property
    // evidence even though it yields no scope keys: adoption fails
    // closed rather than reverting to the fail-open escape (codex #3431
    // r12 P1). Only the true no-evidence estimate (no id, no structured
    // parse) keeps the historical fail-open adopt.
    if (!estimateStreet) {
      if (estimate.property_id) return false;
      const { parseEstimateAddress } = require('../services/estimate-property-linkage');
      const parts = parseEstimateAddress(estimate.address);
      return !(parts && parts.partial === false);
    }
    let candStreet = scopeKeys.candidateKey(cand?.service_address_line1, cand?.service_address_line2, cand?.service_address_city, cand?.service_address_zip);
    // Candidates here always carry source_estimate_id IS NULL (the selector
    // adopts only unclaimed rows), so source-estimate locality recovery can
    // never apply (codex #3248 r7). Fully-unstamped rows fall back to the
    // customer's fully-qualified primary address.
    candStreet = candStreet || await primaryStreet();
    if (!candStreet || scopeKeyLacksLocality(candStreet)) return false;
    // Street-only ESTIMATE key (partial legacy parse — codex #3431 r3 P1):
    // sameScopeKey wildcards the locality segments the estimate lacks, so a
    // same-named street in ANOTHER city would otherwise match. The only
    // locality evidence a street-only estimate has is the customer's primary:
    // when the estimate's street IS the primary street, the candidate must
    // share the primary's locality; a street-only estimate whose street
    // differs from the primary has no locality evidence at all — fail closed
    // (the slot picker books the quoted property a fresh visit).
    if (scopeKeyLacksLocality(estimateStreet)) {
      const primary = await primaryStreet();
      const streetOf = (key) => String(key || '').split('|')[0];
      if (!primary || streetOf(primary) !== streetOf(estimateStreet)) return false;
      return sameScopeKey(candStreet, estimateStreet) && scopeKeysShareLocality(candStreet, primary);
    }
    // SHARED locality evidence required, not merely absence of
    // contradiction (codex #3431 r6 P1): a city-only estimate key against
    // a zip-only stamped candidate wildcards through sameScopeKey with
    // ZERO common evidence — a same-named street in another city would
    // adopt. Both keys are guaranteed at least one locality field here
    // (locality-less candidates were refused above; a locality-less
    // estimate key took the primary-borrow branch), so requiring a shared
    // field only rejects disjoint-evidence pairs. Adoption consumes a real
    // visit — refusing sends the customer to the slot picker, the safe
    // direction.
    return sameScopeKey(candStreet, estimateStreet) && scopeKeysShareLocality(candStreet, estimateStreet);
  };
}

async function findLinkedUpcomingAppointment(estimate = {}, estData = null, opts = {}) {
  const conn = opts.database || db;
  const requestedId = opts.appointmentId ? String(opts.appointmentId) : '';
  const data = estData || parseEstimateDataSafe(estimate);
  const linkedId = data?.scheduled_service_id ? String(data.scheduled_service_id) : '';
  const today = etDateString();
  if (!linkedId && !estimate.id) return null;

  // Column refs are table-qualified: the customer-wide fallback left-joins
  // `services` for catalog identity (codex #3228 r5), and unqualified `id`
  // in ORDER BY would be ambiguous on that query.
  const baseQuery = () => conn('scheduled_services')
    .whereIn('scheduled_services.status', ['pending', 'confirmed'])
    .where('scheduled_services.scheduled_date', '>=', today)
    .where((builder) => {
      if (estimate.customer_id) {
        builder.whereNull('scheduled_services.customer_id')
          .orWhere('scheduled_services.customer_id', estimate.customer_id);
      } else {
        builder.whereNull('scheduled_services.customer_id');
      }
    })
    .andWhere((builder) => {
      builder.whereNull('scheduled_services.reservation_expires_at')
        .orWhereRaw('scheduled_services.reservation_expires_at > NOW()');
    })
    // Callback visits are NEVER adoption candidates (codex #3228 r21):
    // is_callback=true intentionally makes completion treat the visit as
    // FREE (the covered re-service contract), so adopting one would reprice
    // a free callback while the sold billable first application is never
    // represented by a normal appointment.
    .andWhere((builder) => {
      builder.whereNull('scheduled_services.is_callback')
        .orWhere('scheduled_services.is_callback', false);
    })
    .orderBy('scheduled_services.scheduled_date', 'asc')
    .orderBy('scheduled_services.window_start', 'asc')
    // Unique final key: scheduled_date + window_start is not a total order
    // (bundled/multi-property visits tie), and the fallback below paginates —
    // without a stable tiebreaker LIMIT/OFFSET pages can repeat or skip tied
    // rows and miss a same-family appointment (codex #3228 r2).
    .orderBy('scheduled_services.id', 'asc');

  const q = baseQuery()
    // Catalog identity travels with the linked row too (codex #3228 r8) —
    // its family gate below must classify the same catalog-first way the
    // customer-wide fallback does.
    .leftJoin('services', 'services.id', 'scheduled_services.service_id')
    .select(
      'scheduled_services.*',
      'services.service_key as catalog_service_key',
      'services.name as catalog_service_name',
    )
    .where((builder) => {
      if (linkedId) builder.where('scheduled_services.id', linkedId);
      if (estimate.id) builder.orWhere('scheduled_services.source_estimate_id', estimate.id);
    });

  if (requestedId) q.where('scheduled_services.id', requestedId);
  let row = await q.first();

  // The family/mode gate applies to ESTIMATE-LINKED rows too (codex #3228
  // r8 P1): a mixed estimate whose linked row is a recurring-family visit
  // must not adopt it when the customer selects a cross-family one-time
  // option — acceptance would commit the linked row, overwrite its
  // estimated_price, and the selected one-time service would get no booking.
  // The gate is scoped by the same serviceMode(s) the caller passed. Legacy
  // exemption: when the estimate has NO derivable service families under ANY
  // mode (guarantee-only / invoice-only shapes with no service lists), the
  // explicit link keeps its historical precedence.
  const anyModeFamilyKeys = new Set([
    ...estimateFamilyKeysForAdoption(estimate, data, { serviceMode: 'recurring' }),
    ...estimateFamilyKeysForAdoption(estimate, data, { serviceMode: 'one_time' }),
  ]);
  const familyKeys = estimateFamilyKeysForAdoption(estimate, data, {
    serviceMode: opts.serviceMode,
    serviceModes: opts.serviceModes,
  });
  if (row && anyModeFamilyKeys.size > 0 && !appointmentMatchesEstimateFamily(row, familyKeys)) {
    row = null;
  }

  // Customer-wide fallback (gated): a customer who already has an upcoming
  // appointment for the SAME service family shouldn't be pushed through the
  // slot picker again — the acceptance contract swaps the scheduler for
  // payment options instead. Estimate-linked rows always take precedence
  // (query above). Restricted to rows this customer owns that no other
  // estimate has claimed (source_estimate_id null) and that aren't an
  // in-flight reservation hold, so an offered row can't 409 at accept time —
  // the accept-path UPDATE requires these same conditions.
  //
  // FAMILY-SCOPED (owner case 2026-08-05): this fallback used to offer ANY
  // upcoming appointment, so an existing quarterly-pest customer accepting a
  // tree & shrub ADD-ON plan had the pest visit adopted as the add-on's
  // first visit — the slot picker never rendered, the accept stamped the
  // add-on's per-visit price over the pest visit's price, and the
  // duplicate-series guard then matched the (pest) reserved row's family so
  // no tree & shrub series was ever seeded. Only a row whose service family
  // this estimate actually covers may stand in for its first visit;
  // cross-family accepts fall through to the standard slot pick.
  if (!row && estimate.customer_id
    && featureGates.isEnabled('estimateExistingApptCustomerWide')) {
    // PROPERTY-SCOPED for EVERY estimate with property evidence (grouped
    // scoping shipped in codex #3244 r8; widened to ungrouped estimates
    // after the 08-15 cross-property accept incident — see
    // makeAdoptionPropertyScope above): a
    // new/secondary property's accept must not adopt an upcoming visit at
    // another of the customer's properties — the adopted row gets stamped
    // to this estimate, repriced, and the accepted property ends up with
    // NO booked visit while linkage can no longer correct the
    // already-linked row. Fails CLOSED on candidates whose property can't
    // be located; the slot picker books the quoted property a fresh visit
    // instead.
    const candidateAtQuotedProperty = makeAdoptionPropertyScope(conn, estimate);
    if (familyKeys.size > 0) {
      // Page through the candidate list until a same-family row appears — a
      // fixed pre-filter LIMIT would hide a valid later appointment behind a
      // wall of seeded cross-family visits (codex #3228 r1). The family
      // filter can't move into SQL without a second, divergent copy of the
      // service classifier, so pagination does the bounding instead.
      const CANDIDATE_PAGE_SIZE = 50;
      for (let offset = 0; !row; offset += CANDIDATE_PAGE_SIZE) {
        const cw = baseQuery()
          .where('customer_id', estimate.customer_id)
          .whereNull('source_estimate_id')
          .whereNull('reservation_expires_at')
          // Candidate rows carry their catalog identity so classification
          // survives stale service_type labels (codex #3228 r5).
          .leftJoin('services', 'services.id', 'scheduled_services.service_id')
          .select(
            'scheduled_services.*',
            'services.service_key as catalog_service_key',
            'services.name as catalog_service_name',
          );
        if (requestedId) cw.where('scheduled_services.id', requestedId);
        const candidates = await cw.limit(CANDIDATE_PAGE_SIZE).offset(offset);
        if (!Array.isArray(candidates) || candidates.length === 0) break;
        row = null;
        for (const cand of candidates) {
          if (!appointmentMatchesEstimateFamily(cand, familyKeys)) continue;
          if (!(await candidateAtQuotedProperty(cand))) continue;
          row = cand;
          break;
        }
        if (candidates.length < CANDIDATE_PAGE_SIZE) break;
      }
    }
  }

  if (!row) return null;
  if (requestedId && String(row.id) !== requestedId) return null;
  return row;
}

// Legacy name concatenations ("${first} ${last}") baked literal "undefined"/
// "null" into some stored names ("Deborah undefined"). Strip those tokens so
// they never reach a customer-facing page; a name that IS only such a token
// collapses to '' so the caller's fallback chain takes over.
function cleanStoredName(value) {
  return String(value == null ? '' : value)
    .trim()
    .replace(/(?:^|\s)(?:undefined|null)(?=\s|$)/gi, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

// The estimate hero lists the customer's own contact block (name / email /
// phone / service address), but estimate rows are minted by several paths
// (admin UI, Intelligence Bar, lead webhook) that only stamp the fields they
// were given — a row created with just a name + phone renders an incomplete
// block even when the linked customer or lead record has the rest on file.
// Fill the gaps at read time, display-only: the estimate's own columns stay
// authoritative when set, then the linked customer (customer_id), then the
// linked lead (leads.estimate_id). Never throws — on any lookup failure the
// page simply renders what the estimate row has (today's behavior).
async function resolveEstimateContactFields(estimate = {}, opts = {}) {
  const conn = opts.database || db;
  const out = {
    customerName: cleanStoredName(estimate.customer_name) || null,
    customerEmail: String(estimate.customer_email || '').trim() || null,
    customerPhone: String(estimate.customer_phone || '').trim() || null,
    address: String(estimate.address || '').trim() || null,
  };
  const complete = () => out.customerName && out.customerEmail && out.customerPhone && out.address;
  if (complete()) return out;

  const fillFrom = ({ name, email, phone, address }) => {
    out.customerName = out.customerName || cleanStoredName(name) || null;
    out.customerEmail = out.customerEmail || String(email || '').trim() || null;
    out.customerPhone = out.customerPhone || String(phone || '').trim() || null;
    out.address = out.address || String(address || '').trim() || null;
  };

  try {
    if (estimate.customer_id) {
      const customer = await conn('customers')
        .where({ id: estimate.customer_id })
        .first('first_name', 'last_name', 'email', 'phone', 'address_line1', 'address_line2', 'city', 'state', 'zip');
      if (customer) {
        // Region-only output ("Venice, FL 34285" with no street) is worse
        // than leaving the gap for the lead fallback below — customers rows
        // minted with default city/state but a blank street must not block
        // the lead's complete address. Street line required.
        const customerStreet = String(customer.address_line1 || '').trim();
        fillFrom({
          name: [cleanStoredName(customer.first_name), cleanStoredName(customer.last_name)].filter(Boolean).join(' '),
          email: customer.email,
          phone: customer.phone,
          address: customerStreet
            ? formatAddress({
              line1: [customerStreet, String(customer.address_line2 || '').trim()].filter(Boolean).join(', '),
              city: customer.city,
              state: customer.state,
              zip: customer.zip,
            })
            : null,
        });
      }
    }
    if (!complete() && estimate.id) {
      const lead = await conn('leads')
        .where({ estimate_id: estimate.id })
        .whereNull('deleted_at')
        .orderBy('created_at', 'desc')
        .first('first_name', 'last_name', 'email', 'phone', 'address');
      if (lead) {
        fillFrom({
          name: [cleanStoredName(lead.first_name), cleanStoredName(lead.last_name)].filter(Boolean).join(' '),
          email: lead.email,
          phone: lead.phone,
          address: lead.address,
        });
      }
    }
  } catch (err) {
    logger.warn(`[estimate-public] contact fallback lookup failed for estimate ${estimate.id}: ${err.message}`);
  }
  return out;
}

async function renderTemplate(templateKey, vars, fallback, context = {}) {
  const body = await renderEditableSmsTemplate(templateKey, vars, context);
  return body || fallback;
}

async function renderEditableSmsTemplate(templateKey, vars, context = {}) {
  try {
    if (typeof smsTemplatesRouter.getTemplate === 'function') {
      const body = await smsTemplatesRouter.getTemplate(templateKey, vars, context);
      if (body) return body;
    }
  } catch { /* fall through */ }
  return null;
}

